/* @autogenerated */
package net.civeira.phylax.feature.observe.store;

import java.util.List;
import java.util.Set;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

class SqlTelemetryStoreUnitTest {

  @Test
  @DisplayName("Text column by engine, levels from a minimum, and a portable WHERE with escaped LIKE")
  void portable() {
    Assertions.assertEquals("TEXT", SqlTelemetryStore.textType("PostgreSQL"));
    Assertions.assertEquals("MEDIUMTEXT", SqlTelemetryStore.textType("MariaDB"));
    Assertions.assertEquals("CLOB", SqlTelemetryStore.textType("H2"));
    Assertions.assertEquals(List.of("WARN", "ERROR", "FATAL"),
        SqlTelemetryStore.levelsFrom("warning"));
    SqlTelemetryStore.Where where =
        new SqlTelemetryStore.Where().between(1, 2).sources(Set.of("api")).like("50%_off!");
    Assertions.assertEquals(
        " WHERE ts >= ? AND ts < ? AND src IN (?) AND LOWER(payload) LIKE ? ESCAPE '!'",
        where.sql());
    Assertions.assertEquals("%50!%!_off!!%", where.args().get(3));
    Assertions.assertEquals(" WHERE 1 = 0", new SqlTelemetryStore.Where().in("x", List.of()).sql());
  }
}
